#include <stdio.h>
#include <stdlib.h>

int compare(const void *a, const void *b) {
    int int_a = *(int*)a;
    int int_b = *(int*)b;
    return int_a - int_b;
}

int main() {
    int arr[] = {42, 10, 5, 100};
    int n = 4;

    qsort(arr, n, sizeof(int), compare);

    printf("Sorted: %d %d %d %d\n", arr[0], arr[1], arr[2], arr[3]);
    return 0;
}
